package com.yeyamo_mobile.api.commerce_service.application;
import static org.junit.jupiter.api.Assertions.assertThrows;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.Instant;import java.util.Optional;import org.junit.jupiter.api.Test;
import com.yeyamo_mobile.api.commerce_service.messaging.OutboxService;import com.yeyamo_mobile.api.commerce_service.persistence.*;import static com.yeyamo_mobile.api.commerce_service.domain.CommerceTypes.*;
class AdminCommerceServiceTest{
 @Test void rejectsPercentageAboveOneHundred(){PromotionRepository promotions=mock(PromotionRepository.class);when(promotions.findByIdempotencyKey("key")).thenReturn(Optional.empty());AdminCommerceService service=new AdminCommerceService(promotions,mock(CommissionRepository.class),mock(CommerceAuditRepository.class),mock(OutboxService.class));var command=new AdminCommerceService.PromotionCommand(null,"PROMO","Promo",null,DiscountType.PERCENTAGE,new BigDecimal("101"),null,BigDecimal.ZERO,null,Instant.now(),Instant.now().plusSeconds(3600),1L,1L,PromotionStatus.ACTIVE);assertThrows(IllegalArgumentException.class,()->service.createPromotion(command,"key","admin"));}
 @Test void rejectsInvalidCommissionDates(){CommissionRepository commissions=mock(CommissionRepository.class);when(commissions.findByIdempotencyKey("key")).thenReturn(Optional.empty());AdminCommerceService service=new AdminCommerceService(mock(PromotionRepository.class),commissions,mock(CommerceAuditRepository.class),mock(OutboxService.class));Instant now=Instant.now();var command=new AdminCommerceService.CommissionCommand(null,ProductType.BOOKING_ORDER,new BigDecimal("10"),BigDecimal.ZERO,null,"XAF",1,now,now.minusSeconds(1));assertThrows(IllegalArgumentException.class,()->service.createCommission(command,"key","admin"));}
}
